            aOrbiterK = ((aWandererC + RotL64(aIngress, 13U)) + RotL64(aCarry, 35U)) + 0xC8E0B0E1BC044458ULL;
            aOrbiterJ = ((aWandererB + RotL64(aScatter, 60U)) + RotL64(aCarry, 11U)) + 0x9E572F7A839A5DFBULL;
            aOrbiterD = ((aWandererE + RotL64(aPrevious, 35U)) + 0x93816C32C2942124ULL) + aOASaltE[(((511U - aIndex) + 93U)) & S_SALT1];
