            //
            aOrbiterC = (aOrbiterC + aOrbiterB) + 0x0855833C9921B835ULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterC) ^ 0x04D2ADD063460639ULL) ^ aOUSaltG[(((511U - aIndex) + 145U)) & S_SALT1];
            aOrbiterI = RotL64((aOrbiterI * 0xD60DA833D3815459ULL), 43U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterF) + 0x5A23E4D53B8F20F3ULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterH) ^ 0x90CF1AE96F94A765ULL) ^ aOUSaltF[((aIndex + 343U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0x7158AC5F26CF6E7BULL), 23U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterJ) + 0x498B2695E2DDCA6BULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterB) ^ 0x15744C9E891686A9ULL) ^ aOUSaltA[(((511U - aIndex) + 264U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0x4B520E7D09F573B9ULL), 51U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterG) + 0xC8BF6DA27B7B83A7ULL) + aOUSaltC[((aIndex + 44U)) & S_SALT1];
            aOrbiterC = (aOrbiterC ^ aOrbiterD) ^ 0xCA30DF4F71D7F098ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x28415A9AB9126735ULL), 27U);
            //
            aOrbiterF = ((aOrbiterF + aOrbiterI) + 0xBF93BF3AA577EC1BULL) + aOUSaltE[(((511U - aIndex) + 335U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterF) ^ 0x09B8774A228F16BDULL;
            aOrbiterD = RotL64((aOrbiterD * 0x31BF2772979938DBULL), 11U);
