            //
            aOrbiterI = (aOrbiterI + aOrbiterH) + 0x7D50DE1B28C1304FULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterI) ^ 0x2AFD52CF87F2C5DEULL) ^ aOUSaltD[((aIndex + 386U)) & S_SALT1];
            aOrbiterG = RotL64((aOrbiterG * 0x80E955DEC351844BULL), 35U);
