            aOrbiterF = (((aWandererH + RotL64(aPrevious, 37U)) + RotL64(aCarry, 5U)) + 0x641BC5B301940CAAULL) + aOASaltF[((aIndex + 61U)) & S_SALT1];
            aOrbiterC = (aWandererF + RotL64(aScatter, 57U)) + 0x0C3D8F5B74C24979ULL;
