            aOrbiterH = (aOrbiterH + aOrbiterD) + 0xAE1CF61ADE7BCC9BULL;
            aOrbiterC = (aOrbiterC ^ aOrbiterH) ^ 0xD7E0F46BA9C68088ULL;
            aOrbiterC = RotL64((aOrbiterC * 0x9EF84DB5F6DCA58FULL), 3U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterC) + 0x3BDEDFCDCD445E10ULL;
