            aOrbiterJ = (aWandererJ + RotL64(aPrevious, 43U)) + 0x8E2E64B115992DA6ULL;
            aOrbiterD = (aWandererB + RotL64(aScatter, 60U)) + 0x365E0A8F7F797C85ULL;
            aOrbiterC = (aWandererI + RotL64(aIngress, 41U)) + 0xB58464E3E07E0FEEULL;
