            aWandererD = aWandererD + ((RotL64(aScatter, 11U) + RotL64(aOrbiterC, 35U)) + aOrbiterA);
            aWandererC = aWandererC ^ (((RotL64(aPrevious, 60U) + RotL64(aOrbiterE, 19U)) + aOrbiterH) + aWUSaltE[(((511U - aIndex) + 245U)) & S_SALT1]);
