            //
            aIngress = RotL64(aOrbiterD, 27U) ^ aOrbiterF;
            aIngress = aIngress + (RotL64(aOrbiterH, 5U) ^ aOrbiterJ);
            aIngress = aIngress + (RotL64(aOrbiterG, 12U) ^ aOrbiterE);
            aIngress = aIngress + RotL64(aOrbiterI, 51U);
