            //
            aOrbiterK = ((aWandererE + RotL64(aScatter, 57U)) + 0xE484FDD45EE0A6D4ULL) + aOASaltF[((aIndex + 133U)) & S_SALT1];
            aOrbiterB = (aWandererG + RotL64(aIngress, 27U)) + 0x40FDD0888967B5A9ULL;
            aOrbiterG = ((aWandererC + RotL64(aCross, 11U)) + 0x3325C55507AF840CULL) + aOASaltD[((aIndex + 183U)) & S_SALT1];
            aOrbiterH = ((aWandererF + RotL64(aPrevious, 37U)) + RotL64(aCarry, 11U)) + 0x121B393E5D92F02EULL;
            aOrbiterI = (((aWandererK + RotL64(aScatter, 43U)) + RotL64(aCarry, 43U)) + 0x91FB436E5B882FAFULL) + aOASaltG[(((511U - aIndex) + 19U)) & S_SALT1];
            aOrbiterJ = (((aWandererH + RotL64(aCross, 51U)) + RotL64(aCarry, 29U)) + 0x6113617EC5860A1AULL) + aOASaltB[(((511U - aIndex) + 15U)) & S_SALT1];
            aOrbiterA = ((aWandererB + RotL64(aIngress, 20U)) + 0xB89F6E442D95B06CULL) + aOASaltH[((aIndex + 90U)) & S_SALT1];
