            //
            aOrbiterG = (aOrbiterG + aOrbiterA) + 0x36C44FC683CDCBE9ULL;
            aOrbiterJ = (aOrbiterJ ^ aOrbiterG) ^ 0x1CA4C81FB8BECEDFULL;
            aOrbiterJ = RotL64((aOrbiterJ * 0x0CD1B8A79834DA1DULL), 37U);
            //
            aOrbiterJ = ((aOrbiterJ + aOrbiterK) + 0xC70D0D907AADCC63ULL) + aOUSaltG[((aIndex + 33U)) & S_SALT1];
            aOrbiterH = ((aOrbiterH ^ aOrbiterJ) ^ 0xEEF6F1B35EA49BCEULL) ^ aOUSaltC[(((511U - aIndex) + 100U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xCDD89846DC69B3D7ULL), 43U);
            //
            aOrbiterB = (aOrbiterB + aOrbiterH) + 0x8D6375D064F74E2BULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterB) ^ 0x195958ACEB459919ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x1EA71F8DEA703383ULL), 51U);
            //
            aOrbiterA = (aOrbiterA + aOrbiterI) + 0xC5E71486CF30292BULL;
            aOrbiterK = ((aOrbiterK ^ aOrbiterA) ^ 0x85D9BEF8B30BADE9ULL) ^ aOUSaltD[((aIndex + 435U)) & S_SALT1];
            aOrbiterK = RotL64((aOrbiterK * 0xC1ACB3263451C833ULL), 29U);
